#include <WiFi.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ========== НАСТРОЙКИ ЭКРАНА ==========
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1
#define SCREEN_ADDRESS 0x3C  // Адрес I2C (0x3C или 0x3D)
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// ========== ПИНЫ ДЛЯ ESP32-C3 ==========
#define OLED_SDA 4
#define OLED_SCL 5

void setup() {
  Serial.begin(115200);

  // Инициализация I2C для ESP32-C3
  Wire.begin(OLED_SDA, OLED_SCL);

  // Инициализация экрана
  if(!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println("OLED не найден!");
    while(true); // Остановка, если экран не подключен
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Wi-Fi Scanner");
  display.println("Запуск...");
  display.display();
  delay(2000);

  // Включаем Wi-Fi в режиме станции
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
}

void loop() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("=== Wi-Fi Сети ===");

  // Сканирование
  int networkCount = WiFi.scanNetworks();

  if (networkCount == 0) {
    display.println("Сетей не найдено");
  } else {
    // Показываем до 5 самых сильных сетей
    int showCount = min(networkCount, 5);
    for (int i = 0; i < showCount; i++) {
      String ssid = WiFi.SSID(i);
      int rssi = WiFi.RSSI(i);
      int channel = WiFi.channel(i);

      if (ssid.length() == 0) ssid = "Hidden";
      if (ssid.length() > 12) ssid = ssid.substring(0, 12) + ".";

      String line = String(i+1) + ":" + ssid + " " + String(channel) + "ch " + String(rssi) + "dBm";
      if (line.length() > 20) line = line.substring(0, 20);
      display.println(line);
    }

    if (networkCount > 5) {
      display.print("...и еще ");
      display.print(networkCount - 5);
      display.println(" сетей");
    }
  }

  display.setCursor(0, 56);
  display.print("Всего: ");
  display.print(networkCount);
  display.print("  обновление...");
  display.display();

  WiFi.scanDelete();
  delay(5000); // Обновление каждые 5 секунд
}
